public class AVAConnectionBPToBP extends common
{
}

Method.Source:
/// <summary>
///    AVA <c>find</c> method.
/// </summary>
/// <param name="_kbvBuildingProjectIDA">
///    <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <param name="_connectionTypeId">
///    <c>AVAConnectionTypeId</c> as type
/// </param>
/// <param name="_kbvBuildingProjectIDB">
///    <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <param name="_forUpdate">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>AVAConnectionBPToBP</c> as return value
/// </returns>
public static AVAConnectionBPToBP find( KCS_KBVBuildingProjectID    _kbvBuildingProjectIDA,
                                        AVAConnectionTypeId         _connectionTypeId,
                                        KCS_KBVBuildingProjectID    _kbvBuildingProjectIDB,
                                        boolean                     _forUpdate              = false)
{
    AVAConnectionBPToBP record;

    record.selectForUpdate(_forUpdate);

    if(_kbvBuildingProjectIDA && _kbvBuildingProjectIDB)
    {
        select firstonly record
        index hint KCS_KBVBPToBPIdx
        where   record.KCS_KBVBuildingProjectIDA    == _kbvBuildingProjectIDA
            &&  record.AVAConnectionTypeId          == _connectionTypeId
            &&  record.KCS_KBVBuildingProjectIDB    == _kbvBuildingProjectIDB;
    }

    return record;
}

/// <summary>
