/// <summary>
/// AVA
/// </summary>
/// <param name = "_kcs_KBVBuildingProjectID">KCS_KBVBuildingProjectID</param>
/// <returns>boolean</returns>
static boolean existRecForBP(   KCS_KBVBuildingProjectID    _kcs_KBVBuildingProjectID)
{
    boolean                 retVal;

    AVAConnectionBPToBP  conn;

    if (!_kcs_KBVBuildingProjectID )
    {
        return false;
    }

    select firstonly RecId
    from    conn
    where   conn.KCS_KBVBuildingProjectIDB  == _kcs_KBVBuildingProjectID || conn.KCS_KBVBuildingProjectIDA == _kcs_KBVBuildingProjectID;

    if(conn.RecId)
    {
        retVal = true;
    }

    return retVal;
}
